import { Link } from 'react-router-dom';
import suffixLogo from '../../assets/img/Suffix-Logo-white.png';
import bacco from '../../assets/img/bacco.png';
import cisco from '../../assets/img/cisco.png';
import fort from '../../assets/img/fort.png';
import basis from '../../assets/img/basis.svg';
import cer1 from '../../assets/img/certificate (1).png';
import cer2 from '../../assets/img/certificate (2).png';
import { CURRENT_YEAR } from '../../helpers/Constant';

const Footer = () => {
  return (
    <footer
      id="footer"
      className="relative overflow-hidden text-white"
      style={{
        background:
          'linear-gradient(180deg,#111111 0%, #1b130d 35%, #2d0a07 70%, #6b0000 100%)',
      }}
    >
      {/* Glow Effects */}
      <div className="absolute top-0 left-0 w-full h-full opacity-20 pointer-events-none">
        <div
          style={{
            width: 400,
            height: 400,
            borderRadius: '50%',
            background: '#ff9900',
            filter: 'blur(120px)',
            position: 'absolute',
            top: -100,
            left: -80,
          }}
        />
        <div
          style={{
            width: 350,
            height: 350,
            borderRadius: '50%',
            background: '#ff0000',
            filter: 'blur(140px)',
            position: 'absolute',
            right: -100,
            bottom: -100,
          }}
        />
      </div>

      <div className="container position-relative py-5">
        {/* Top Grid */}
        <div className="row g-5 border-bottom border-secondary pb-5">
          {/* Company Info */}
          <div className="col-lg-3 col-md-6">
            <img
              src={suffixLogo}
              alt="site logo"
              style={{ width: 170, marginBottom: 25 }}
            />

            <p
              className="text-light"
              style={{ lineHeight: '1.8', fontSize: 14 }}
            >
              Cha-70,70/A, Rupayan Millennium Square (9A), Progoti Sharoni,
              North Badda, Gulshan, Dhaka-1212, Bangladesh.
              <br />
              E-mail: info@suffixit.com
              <br />
              Phone: +88 01958 424000
            </p>

            <div className="d-flex gap-3 mt-4">
              <a href="https://www.facebook.com/suffixworld/" target="_blank">
                <i className="fab fa-facebook-f" />
              </a>
              <a href="#" target="_blank">
                <i className="fab fa-twitter" />
              </a>
              <a href="https://www.linkedin.com/company/suffix-it-limited/mycompany/">
                <i className="fab fa-linkedin-in" />
              </a>
            </div>

            {/* Certifications */}
            <div className="mt-5">
              <h5 className="fw-bold mb-3 text-uppercase">Certifications</h5>

              <div className="d-flex gap-3 flex-wrap">
                {[cer1, cer2].map((img, i) => (
                  <div
                    key={i}
                    className="bg-white rounded-4 shadow-sm d-flex align-items-center justify-content-center"
                    style={{ width: 90, height: 90 }}
                  >
                    <img
                      src={img}
                      alt="certificate"
                      style={{ width: 60, height: 60 }}
                    />
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Product */}
          <div className="col-lg-3 col-md-6">
            <h5 className="fw-bold mb-4 text-uppercase">Products</h5>

            <ul className="list-unstyled footer-links">
              <li><Link to="/product/payroll-system">RUPANTOR HCM/HR/Payroll</Link></li>
              <li><Link to="/product/provident-fund">SUFFIX PF</Link></li>
              <li><Link to="/product/rupantor-erp">Rupantor ERP</Link></li>
              <li><Link to="/product/e-commerce">E-commerce</Link></li>
              <li><Link to="/product/field-force-management">Field Force Management</Link></li>
              <li><Link to="/product/interconnect-billing">Suffix Interconnect Billing</Link></li>
              <li><Link to="/product/hotel-booking-system">Suffix Hotel booking System</Link></li>
              <li><Link to="/product/rupantor-inventory">Rupantor Inventor</Link></li>
              <li><Link to="/product/pos-system">Smart POS & Billing System</Link></li>
              <li><Link to="/product/transformer-monitoring">Smart Transformer Monitoring System</Link></li>
            </ul>
          </div>

          {/* Services */}
          <div className="col-lg-3 col-md-6">
            <h5 className="fw-bold mb-4 text-uppercase">Services</h5>

            <ul className="list-unstyled footer-links">
              <li><Link to="/service/domain-hosting">Domain & Hosting</Link></li>
              <li><Link to="/service/erp-consulting">ERP Consulting</Link></li>
              <li><Link to="/service/web-ecommerce">Web & Ecommerce</Link></li>
              <li><Link to="/service/custom-applications">Custom Applications</Link></li>
              <li><Link to="/service/video-conferencing">Storage & Backup Services</Link></li>
              <li><Link to="/service/mobile-apps">Mobile Apps</Link></li>
              <li><Link to="/service/field-force-management">Field Force Management</Link></li>
              <li><Link to="/service/bulk-sms">Bulk SMS</Link></li>
              <li><Link to="/service/video-conferencing">Suffix Video Conferencing</Link></li>
              <li><Link to="/service/pos-system">Smart POS & Billing System</Link></li>
              <li><Link to="/service/iot">IoT-(Internet of things)</Link></li>
              <li><Link to="/service/it-infrastructure">IT Infrastructure</Link></li>
              <li><Link to="/service/consultancy-system-integrator">Consultancy System Integrator</Link></li>
              <li><Link to="/service/it-ot-security-solution">Comprehensive IT & OT Security Solutions</Link></li>
              <li><Link to="/service/power-cooling">Data Center Power & Cooling</Link></li>
            </ul>
          </div>

          {/* Members / Partnership */}
          <div className="col-lg-3 col-md-6">
            <h5 className="fw-bold mb-4 text-uppercase">Members Of</h5>

            <div className="d-flex flex-column gap-3 mb-5">
              <div className="bg-white rounded-4 p-3 text-center">
                <img src={basis} alt="basis" style={{ width: 140 }} />
              </div>

              <div className="bg-white rounded-4 p-3 text-center">
                <img src={bacco} alt="bacco" style={{ width: 140 }} />
              </div>
            </div>

            <h5 className="fw-bold mb-4 text-uppercase">Partnership</h5>

            <div className="d-flex flex-column gap-3">
              <div className="bg-white rounded-4 p-3 text-center">
                <img
                  src={cisco}
                  alt="cisco"
                  style={{ width: 140, height: 65, objectFit: 'contain' }}
                />
              </div>

              <div className="bg-white rounded-4 p-3 text-center">
                <img
                  src={fort}
                  alt="fort"
                  style={{ width: 140, height: 65, objectFit: 'contain' }}
                />
              </div>
            </div>
          </div>
        </div>

        {/* Bottom Strip */}
        <div className="row pt-4 align-items-center">
          <div className="col-md-6 text-center text-md-start mb-3 mb-md-0">
            <p className="mb-0 text-light small">
              © {CURRENT_YEAR} All Rights Reserved by{' '}
              <a
                href="https://suffixit.com/"
                target="_blank"
                className="text-warning text-decoration-none fw-bold"
              >
                Suffix IT
              </a>
            </p>
          </div>

          <div className="col-md-6">
            <ul className="list-inline text-center text-md-end mb-0 small">
              <li className="list-inline-item mx-2">
                <a href="#" className="text-light text-decoration-none">
                  Privacy & Policy
                </a>
              </li>
              <li className="list-inline-item mx-2">
                <a href="#" className="text-light text-decoration-none">
                  FAQ
                </a>
              </li>
              <li className="list-inline-item mx-2">
                <a href="#" className="text-light text-decoration-none">
                  Terms
                </a>
              </li>
            </ul>
          </div>
        </div>
      </div>

      {/* CSS */}
      <style jsx>{`
        .footer-links li {
          margin-bottom: 10px;
        }

        .footer-links a {
          color: rgba(255, 255, 255, 0.75);
          text-decoration: none;
          font-size: 14px;
          transition: 0.3s ease;
        }

        .footer-links a:hover {
          color: #f9b233;
          padding-left: 6px;
        }

        .fab {
          width: 38px;
          height: 38px;
          border-radius: 50%;
          background: rgba(255, 255, 255, 0.08);
          display: flex;
          align-items: center;
          justify-content: center;
          color: white;
          transition: 0.3s ease;
        }

        .fab:hover {
          background: #f9b233;
          color: #111;
          transform: translateY(-4px);
        }

        h5 {
          letter-spacing: 1px;
          font-size: 15px;
        }

        @media (max-width: 767px) {
          .footer-links a {
            font-size: 13px;
          }
        }
      `}</style>
    </footer>
  );
};

export default Footer;
